import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(point):
        r, c = point
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if not is_valid(start) or not is_valid(goal):
        return []
    if start == goal:
        return [start]

    dist = {(r, c): float('inf') for r in range(rows) for c in range(cols)}
    dist[start] = 0
    heap = [(0, start)]
    prev = {(r, c): None for r in range(rows) for c in range(cols)}
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        current_dist, current = heapq.heappop(heap)
        if current == goal:
            break
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                if dist[(nr, nc)] == float('inf'):
                    dist[(nr, nc)] = current_dist + 1
                    prev[(nr, nc)] = current
                    heapq.heappush(heap, (dist[(nr, nc)], (nr, nc)))

    if prev[goal] is None:
        return []

    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = prev[current]
    return path[::-1]

