def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal are walls or if goal is already reached
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    # Initialize distance and predecessor matrices
    distances = [[-1 for _ in range(cols)] for _ in range(rows)]
    predecessors = [[None for _ in range(cols)] for _ in range(rows)]
    distances[start[0]][start[1]] = 0

    # Bellman-Ford-style relaxation algorithm
    for _ in range(rows * cols):
        updated = False
        for i in range(rows):
            for j in range(cols):
                if distances[i][j] != -1:
                    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < rows and 0 <= nj < cols:
                            if grid[ni][nj] == '.' and distances[ni][nj] == -1:
                                distances[ni][nj] = distances[i][j] + 1
                                predecessors[ni][nj] = (i, j)
                                updated = True
        if not updated:
            break

    # Path reconstruction if goal is reachable
    if distances[goal[0]][goal[1]] == -1:
        return []

    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = predecessors[current[0]][current[1]]

    path.reverse()
    return path if path[0] == start else []

